// matchReq builds a MatchRequest whose item carries the library-relative path in
// its parsed Struct, the way the (Task 07) media-type-agnostic base-scanner
// stamps base fields. tv-parser reads relative_path from there (pathFromParsed).
func matchReq(relPath string) *metadatav1.MatchRequest {
	parsed, _ := structpb.NewStruct(map[string]any{"relative_path": relPath})
	return &metadatav1.MatchRequest{
		Item:       &scannerv1.IdentifyResult{Parsed: parsed},
		ModuleType: "tv",
	}
}

// strField reads a string field from a Struct ("" if absent). Test helper.
func strField(s *structpb.Struct, key string) string {
	if v, ok := s.GetFields()[key]; ok {
		return v.GetStringValue()
	}
	return ""
}

// numField reads a numeric field from a Struct (0 if absent). Test helper.
func numField(s *structpb.Struct, key string) int64 {
	if v, ok := s.GetFields()[key]; ok {
		return int64(v.GetNumberValue())
	}
	return 0
}

// TestMatch is the table test for parserImpl.Match (B3, B7): it drives the moved
// parseTV through the Match RPC and re-homes the TV-parse cases (SxxExx,
// multi-episode, cleanTitle, resolution/release-group, Cyrillic first-class, and
// the movie-style not-applies case) that lived in base-scanner/tvparse_test.go.
func TestMatch(t *testing.T) {
	tests := []struct {
		name       string
		rel        string
		applies    bool
		title      string
		season     int64
		episode    int64
		episodeEnd int64
		hasEnd     bool
		resolution string
		group      string
	}{
		{
			name: "SxxExx + dot separators + resolution", rel: "Show.Name.S01E02.1080p.mkv",
			applies: true, title: "Show Name", season: 1, episode: 2, resolution: "1080p",
		},
		{
			name: "cyrillic title first-class", rel: "Игра престолов S01E01.mkv",
			applies: true, title: "Игра престолов", season: 1, episode: 1,
		},
		{
			name: "multi-episode + resolution + release group", rel: "Show.S01E01E02.1080p.WEB-DL.x264-RG.mkv",
			applies: true, title: "Show", season: 1, episode: 1, episodeEnd: 2, hasEnd: true,
			resolution: "1080p", group: "RG",
		},
		{
			name: "title from parent dir fallback", rel: "Breaking Bad/Season 1/Breaking Bad S01E02.mkv",
			applies: true, title: "Breaking Bad", season: 1, episode: 2,
		},
		{
			name: "movie-style name does not apply", rel: "Random Movie.mkv",
			applies: false,
		},
		// Canonical shapes (unified-parser qa 4.1): the shared grammar's inputs
		// mirrored at this adapter, each pinning THIS package's documented
		// outcome — the apply rule stays SxxExx-only, so the bare-number
		// canonical shapes skip while the 720i resolution vocabulary flows
		// through beside the token.
		{
			name: "trailing-decoration bracket without SxxExx does not apply", rel: "Show_Name_II_[01]_[HEVC].mkv",
			applies: false,
		},
		{
			name: "whole-token 720i is a resolution beside the token", rel: "Show.S02E05.720i.mkv",
			applies: true, title: "Show", season: 2, episode: 5, resolution: "720i",
		},
		{
			// The tagged film degenerate case: the release decoration (year,
			// resolution, codec, group) must not fabricate a season/episode token.
			name: "tagged film does not apply", rel: "Blue Horizon (2019) [WEB-DL 1080p x264] - FanGroup.mkv",
			applies: false,
		},
	}
	p := &parserImpl{}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			res, err := p.Match(context.Background(), matchReq(tc.rel))
			if err != nil {
				t.Fatalf("Match: %v", err)
			}
			if res.GetApplies() != tc.applies {
				t.Fatalf("applies = %v, want %v (reason=%q)", res.GetApplies(), tc.applies, res.GetReason())
			}
			if !tc.applies {
				return
			}
			q := res.GetQuery()
			if got := strField(q, "title"); got != tc.title {
				t.Errorf("title = %q, want %q", got, tc.title)
			}
			if got := numField(q, "season"); got != tc.season {
				t.Errorf("season = %d, want %d", got, tc.season)
			}
			if got := numField(q, "episode"); got != tc.episode {
				t.Errorf("episode = %d, want %d", got, tc.episode)
			}
			gotEnd, hasEnd := q.GetFields()["episode_end"]
			if tc.hasEnd {
				if !hasEnd || int64(gotEnd.GetNumberValue()) != tc.episodeEnd {
					t.Errorf("episode_end = %v (has=%v), want %d", gotEnd, hasEnd, tc.episodeEnd)
				}
			} else if hasEnd {
				t.Errorf("episode_end unexpectedly present = %v", gotEnd)
			}
			if tc.resolution != "" {
				if got := strField(q, "resolution"); got != tc.resolution {
					t.Errorf("resolution = %q, want %q", got, tc.resolution)
				}
			}
			if tc.group != "" {
				if got := strField(q, "release_group"); got != tc.group {
					t.Errorf("release_group = %q, want %q", got, tc.group)
				}
			}
		})
	}
}

// TestConvert drives Match -> Convert (the real producer feeds the real consumer)
// and asserts the normalized metadata shape + the per-field provenance hint
// (plugin_id=="tv-parser", B5). The query from Match is what Convert receives.
func TestConvert(t *testing.T) {
	p := &parserImpl{}
	mr, err := p.Match(context.Background(), matchReq("Show.Name.S01E02.1080p.mkv"))
	if err != nil || !mr.GetApplies() {
		t.Fatalf("Match precondition: err=%v applies=%v", err, mr.GetApplies())
	}
	conv, err := p.Convert(context.Background(), &metadatav1.ConvertRequest{Query: mr.GetQuery()})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	meta := conv.GetMetadata()
	if got := strField(meta, "title"); got != "Show Name" {
		t.Errorf("metadata title = %q, want Show Name", got)
	}
	if got := numField(meta, "season"); got != 1 {
		t.Errorf("metadata season = %d, want 1", got)
	}
	if got := numField(meta, "episode"); got != 2 {
		t.Errorf("metadata episode = %d, want 2", got)
	}
	if got := strField(meta, "resolution"); got != "1080p" {
		t.Errorf("metadata resolution = %q, want 1080p", got)
	}
	// Provenance hint: every metadata field names tv-parser + its version (AC-5).
	prov := conv.GetProvenance()
	if len(prov) == 0 {
		t.Fatal("provenance hint map empty, want one entry per metadata field")
	}
	for field, p := range prov {
		if p.GetPluginId() != pluginID {
			t.Errorf("provenance[%q].plugin_id = %q, want %q", field, p.GetPluginId(), pluginID)
		}
		if p.GetPluginVersion() != pluginVersion {
			t.Errorf("provenance[%q].plugin_version = %q, want %q", field, p.GetPluginVersion(), pluginVersion)
		}
		if p.GetFetchedAt() == nil {
			t.Errorf("provenance[%q].fetched_at nil, want a timestamp", field)
		}
	}
}

// TestMerge asserts INV-namespace-write (B6): Merge writes ONLY the
// sources["tv-parser"] namespace — no other top-level key, no foreign source —
// and returns one view binding per field with source "tv-parser".
func TestMerge(t *testing.T) {
	p := &parserImpl{}
	incoming, _ := structpb.NewStruct(map[string]any{
		"title":   "Show Name",
		"season":  1,
		"episode": 2,
	})
	res, err := p.Merge(context.Background(), &metadatav1.MergeRequest{
		Incoming: incoming,
		PluginId: pluginID,
	})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	data := res.GetDocument().GetData().AsMap()
	if len(data) != 1 {
		t.Fatalf("document top-level keys = %v, want exactly {sources} (INV-namespace-write)", data)
	}
	sources, ok := data["sources"].(map[string]any)
	if !ok {
		t.Fatalf("document has no sources map: %v", data)
	}
	if len(sources) != 1 {
		t.Fatalf("sources namespaces = %v, want exactly {tv-parser}", sources)
	}
	ns, _ := sources[pluginID].(map[string]any)
	if got := ns["title"]; got != "Show Name" {
		t.Errorf("sources.tv-parser.title = %v, want Show Name", got)
	}
	// structpb represents numbers as float64, so season round-trips as 1.0.
	if got := ns["season"]; got != float64(1) {
		t.Errorf("sources.tv-parser.season = %v, want 1", got)
	}
	view := res.GetView()
	if len(view) != len(ns) {
		t.Fatalf("view bindings = %d, want one per metadata field (%d)", len(view), len(ns))
	}
	for _, vb := range view {
		if vb.GetSource() != pluginID {
			t.Errorf("view[%q].source = %q, want %q", vb.GetFieldPath(), vb.GetSource(), pluginID)
		}
	}
}

// TestTVParserSubprocess is the B1/B2 joint smoke test (seam S3): it builds the
// tv-parser binary, launches it as a real go-plugin subprocess, and drives the
// full round-trip — magic-cookie handshake, the domain Plugin.Handshake (proves
// plugin.v1 is served AND advertises the metadata_source capability), and the
// 4-RPC MetadataSource chain (Match/BuildRequest/Convert/Merge, proves
// metadata.v1 is served). It needs no ffprobe (tv-parser is a pure parser).
func TestTVParserSubprocess(t *testing.T) {
	bin := filepath.Join(t.TempDir(), "tv-parser")
	build := exec.Command("go", "build", "-o", bin, ".")
	build.Env = append(os.Environ(), "CGO_ENABLED=0")
	if out, err := build.CombinedOutput(); err != nil {
		t.Fatalf("build tv-parser: %v\n%s", err, out)
	}

	cl := goplugin.NewClient(&goplugin.ClientConfig{
		HandshakeConfig: goplugin.HandshakeConfig{
			ProtocolVersion:  1,
			MagicCookieKey:   magicCookieKey,
			MagicCookieValue: magicCookieValue,
		},
		Plugins:          goplugin.PluginSet{"metadata_source": &sdk.MetadataSourcePlugin{}},
		Cmd:              exec.Command(bin),
		AllowedProtocols: []goplugin.Protocol{goplugin.ProtocolGRPC},
	})
	defer cl.Kill()

	rpcClient, err := cl.Client()
	if err != nil {
		t.Fatalf("go-plugin client: %v", err)
	}
	gc, ok := rpcClient.(*goplugin.GRPCClient)
	if !ok {
		t.Fatal("go-plugin did not negotiate the gRPC protocol")
	}

	// Domain Plugin.Handshake over the shared conn — proves plugin.v1 is served
	// AND advertises ONE metadata_source capability bound to the MetadataSource FQN.
	pconn := pluginv1.NewPluginClient(gc.Conn)
	hr, err := pconn.Handshake(context.Background(), &pluginv1.HandshakeRequest{CoreVersion: minCoreVersion})
	if err != nil {
		t.Fatalf("Plugin.Handshake: %v", err)
	}
	if hr.GetPluginId() != pluginID {
		t.Fatalf("handshake plugin_id = %q, want %q", hr.GetPluginId(), pluginID)
	}
	if len(hr.GetCapabilities()) != 1 ||
		hr.GetCapabilities()[0].GetType() != "metadata_source" ||
		hr.GetCapabilities()[0].GetProtoService() != metadataProtoFQN {
		t.Fatalf("handshake capabilities = %v, want one {metadata_source, %s}", hr.GetCapabilities(), metadataProtoFQN)
	}

	// MetadataSource capability (metadata.v1) over the same conn.
	raw, err := rpcClient.Dispense("metadata_source")
	if err != nil {
		t.Fatalf("dispense metadata_source: %v", err)
	}
	md, ok := raw.(sdk.MetadataSource)
	if !ok {
		t.Fatalf("dispensed %T is not an sdk.MetadataSource", raw)
	}

	// 4-RPC chain round-trip: Match -> BuildRequest -> Convert -> Merge.
	mr, err := md.Match(context.Background(), matchReq("Show.Name.S01E02.1080p.mkv"))
	if err != nil || !mr.GetApplies() {
		t.Fatalf("Match: err=%v applies=%v", err, mr.GetApplies())
	}
	br, err := md.BuildRequest(context.Background(), &metadatav1.BuildRequestRequest{Query: mr.GetQuery()})
	if err != nil {
		t.Fatalf("BuildRequest: %v", err)
	}
	if br.GetSpec() == nil {
		t.Fatal("BuildRequest spec nil, want an empty RequestSpec (Phase A nop)")
	}
	conv, err := md.Convert(context.Background(), &metadatav1.ConvertRequest{Query: mr.GetQuery()})
	if err != nil {
		t.Fatalf("Convert: %v", err)
	}
	if got := strField(conv.GetMetadata(), "title"); got != "Show Name" {
		t.Fatalf("Convert metadata title = %q, want Show Name", got)
	}
	mrg, err := md.Merge(context.Background(), &metadatav1.MergeRequest{Incoming: conv.GetMetadata(), PluginId: pluginID})
	if err != nil {
		t.Fatalf("Merge: %v", err)
	}
	if _, ok := mrg.GetDocument().GetData().AsMap()["sources"]; !ok {
		t.Fatal("Merge document has no sources key")
	}

	// Graceful Shutdown over the shared conn — proves plugin.v1.Shutdown is served.
	if _, err := pconn.Shutdown(context.Background(), &pluginv1.ShutdownRequest{Reason: "test"}); err != nil {
		t.Fatalf("Plugin.Shutdown: %v", err)
	}
}

// TestMatchAdversarialEdges pins the two adapter-local edges the unified-parser
// grammar move exposed (qa adversarial check on the G2 coder's deviations #2
// and #4) at their CURRENT behavior, each verdict recorded where the edge
// diverges from the pre-change adapter.
func TestMatchAdversarialEdges(t *testing.T) {
	p := &parserImpl{}
	match := func(rel string) *metadatav1.MatchResult {
		t.Helper()
		res, err := p.Match(context.Background(), matchReq(rel))
		if err != nil {
			t.Fatalf("Match %q: %v", rel, err)
		}
		if !res.GetApplies() {
			t.Fatalf("Match %q did not apply", rel)
		}
		return res
	}

	// Deviation #2 — the release-group dash rule searches end-anchored over
	// the WHOLE stem (pre-change: only the text after the SxxExx token), and
	// the shared title derivation cuts a trailing bare number but not its
	// dash-letter prefix. The dash-form multi-episode tail named group "E02"
	// under BOTH windows (that edge predates the change), but its title
	// REGRESSED: "Show" before the change, "Show -E" now — the shared
	// grammar's trailing-number cut leaves the "-E" residue. The dash-joined
	// title-token tail is NEW to the group window ("Show-S01E02.mkv" now
	// names the whole token the group; its title is clean). FLAG (qa report):
	// the dash-form multi-episode layout degrades on BOTH fields — a
	// "-E"-suffixed title plus a fabricated release_group "E02" — cosmetic
	// (no season/episode corruption), but a real naming regression worth a
	// gate flag; the pin keeps it visible until the adapter cleans the tail.
	t.Run("release group window", func(t *testing.T) {
		for _, tc := range []struct {
			name, rel, wantGroup, wantTitle string
			wantSeason, wantEpisode         int64
		}{
			{"dash-form multi-episode tail", "Show.S01E01-E02.mkv", "E02", "Show -E", 1, 1},
			{"dash-joined token tail", "Show-S01E02.mkv", "S01E02", "Show", 1, 2},
		} {
			t.Run(tc.name, func(t *testing.T) {
				q := match(tc.rel).GetQuery()
				if got := strField(q, "release_group"); got != tc.wantGroup {
					t.Fatalf("release_group = %q, want %q (pinned current behavior)", got, tc.wantGroup)
				}
				if got := strField(q, "title"); got != tc.wantTitle {
					t.Fatalf("title = %q, want %q (pinned current behavior)", got, tc.wantTitle)
				}
				if got := numField(q, "season"); got != tc.wantSeason || numField(q, "episode") != tc.wantEpisode {
					t.Fatalf("season/episode = %d/%d, want %d/%d", numField(q, "season"), numField(q, "episode"), tc.wantSeason, tc.wantEpisode)
				}
			})
		}
	})

	// Deviation #4 — a token-only stem ("S01E01.mkv") now titles from the
	// shared fallback's token echo, which pre-empts the adapter's parent-dir
	// fallback (pre-change: the text before the token, then the parent dir).
	// The cours layout derives a garbage title under BOTH rules ("Season 1"
	// before, the token echo now — neither is "Breaking Bad"; that needs a
	// grandparent walk). FLAG (qa report): the FLAT layout REGRESSED —
	// "Show/S01E01.mkv" titled "Show" before the change, now "S01E01". Worth
	// a gate flag; the pin keeps the regression visible until the adapter
	// restores the parent-dir fallback for stems carrying no title text.
	t.Run("token-only stem title", func(t *testing.T) {
		for _, tc := range []struct {
			name, rel, wantTitle string
		}{
			{name: "cours layout", rel: "Breaking Bad/Season 1/S01E01.mkv", wantTitle: "S01E01"},
			{name: "flat layout (regressed from the parent-dir title)", rel: "Show/S01E01.mkv", wantTitle: "S01E01"},
		} {
			t.Run(tc.name, func(t *testing.T) {
				res := match(tc.rel)
				if got := strField(res.GetQuery(), "title"); got != tc.wantTitle {
					t.Fatalf("title = %q, want %q (pinned current behavior)", got, tc.wantTitle)
				}
				if got := res.GetConfidence(); got != 1.0 {
					t.Fatalf("confidence = %v, want 1.0 (season/episode + a title)", got)
				}
			})
		}
	})
}
